import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.rZZZX73S.js";var c=JSON.parse(`{"title":"UPnPumpkin","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/upnpumpkin/docs/index.md"},"headers":[],"relativePath":"packages/upnpumpkin/docs/index.md","filePath":"packages/upnpumpkin/docs/index.md","lastUpdated":1791428389000}`),l={name:`packages/upnpumpkin/docs/index.md`},u={id:`upnpumpkin`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/upnpumpkin-v0.0.8`,"aria-label":`Release v0.0.8`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`img`,{class:`component-page-title__icon`,src:`/pumpkin-plugins/packages/upnpumpkin/icon.svg`,alt:``,"aria-hidden":`true`,width:`48`,height:`48`},null,-1),c[1]||=n(`span`,{class:`component-page-title__text`},[t(`UPnPumpkin `),n(`a`,{class:`header-anchor`,href:`#upnpumpkin`,"aria-label":`Permalink to “UPnPumpkin”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.0.8`})])]),c[2]||=r(`<p>UPnPumpkin asks a home router to forward the server&#39;s Java TCP and Bedrock UDP ports using UPnP or NAT-PMP. This lets players outside the local network connect without manually adding router rules when the network supports automatic mapping.</p><p>Install <code>upnpumpkin.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> folder and restart. By default it requests Java port <code>25565</code> and Bedrock port <code>19132</code>. Router leases are renewed halfway through their configured lifetime and are closed when the server stops.</p><h2 id="check-the-mapping" tabindex="-1">Check the mapping <a class="header-anchor" href="#check-the-mapping" aria-label="Permalink to “Check the mapping”">​</a></h2><p>Operators can run <code>/upnp status</code> to see the discovered router, public address, and port states. Run <code>/upnp reload</code> after changing <code>plugins/data/UPnPumpkin/config.toml</code> to re-read settings and update the mappings. A server that already has a public address does not need a router mapping.</p><p>UPnPumpkin can also accept port requests from other plugins. Requests are enabled by default and limited to 16 open ports per plugin. A requesting plugin must stop its watcher when it no longer needs a port; unused requests expire after five minutes.</p><h2 id="network-requirements" tabindex="-1">Network requirements <a class="header-anchor" href="#network-requirements" aria-label="Permalink to “Network requirements”">​</a></h2><p>The router must have UPnP or NAT-PMP enabled, and the host must have a public route through that router. Carrier-grade NAT cannot be bypassed with a mapping. A second router or a container network that blocks multicast can prevent discovery; configure the router search address when multicast is blocked. UPnPumpkin refuses routers on its built-in unsupported-router list before opening ports.</p><p>UPnP is available to devices on the local network. Run it only on a network you trust. See the troubleshooting page for common discovery and reachability failures.</p>`,8)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};